    char circolo[100];

    printf("Inserisci il nome del giocatore:\n");
    if (fgets(giocatore, (int)sizeof(giocatore), stdin) == nullptr) {
        printf("Errore: lettura del giocatore interrotta.\n");
        return 1;
    }

    printf("Inserisci il circolo di appartenenza:\n");
    if (fgets(circolo, (int)sizeof(circolo), stdin) == nullptr) {
