    printf("Circolo: %s", circolo);
    return 0;
}

#include <stdio.h>

int main(void) {
    char riga[128];
    double energia_kwh = 0.0;
    double tariffa_kwh = 0.0;
    int minuti_sosta = 0;
    char codice_tessera = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%lf %lf", &energia_kwh, &tariffa_kwh) != 2) {
        printf("Errore: prima riga non valida.\n");
        return 1;
    }
    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr ||
        sscanf(riga, "%d %c", &minuti_sosta, &codice_tessera) != 2) {
        printf("Errore: seconda riga non valida.\n");
        return 1;
    }
    if (energia_kwh < 0.0 || tariffa_kwh < 0.0 || minuti_sosta < 0) {
        printf("Errore: valori negativi non ammessi.\n");
        return 1;
    }

    double aliquota_sconto = 0.0;
    switch (codice_tessera) {
        case 'A':
        case 'a':
            aliquota_sconto = 0.10;
            break;
        case 'O':
        case 'o':
            aliquota_sconto = 0.0;
            break;
        default:
            printf("Errore: codice tessera non valido.\n");
            return 1;
    }

    double costo_lordo = energia_kwh * tariffa_kwh;
    double sconto = costo_lordo * aliquota_sconto;
    double totale = costo_lordo - sconto;
    printf("Energia: %.2f kWh\n", energia_kwh);
    printf("Costo lordo: %.2f euro\n", costo_lordo);
    printf("Sconto: %.2f euro\n", sconto);
    printf("Totale da pagare: %.2f euro\n", totale);
    if (minuti_sosta > 0) {
        double potenza_media = energia_kwh / (minuti_sosta / 60.0);
        printf("Potenza media: %.2f kW\n", potenza_media);
    } else {
        printf("Potenza media: non calcolabile\n");
    }
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    char riga[128];
    int fila = 0;
    int posto = 0;
    char extra = '\0';

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) {
        fprintf(stderr, "Errore: fine dell'input durante la lettura della fila.\n");
        return EXIT_FAILURE;
    }
    if (sscanf(riga, "%d %c", &fila, &extra) != 1) {
        fprintf(stderr, "Errore: formato della fila non valido.\n");
        return EXIT_FAILURE;
    }
    if (fila < 1 || fila > 20) {
        fprintf(stderr, "Errore: la fila deve essere compresa tra 1 e 20.\n");
        return EXIT_FAILURE;
    }

    if (fgets(riga, (int)sizeof(riga), stdin) == nullptr) {
        fprintf(stderr, "Errore: fine dell'input durante la lettura del posto.\n");
        return EXIT_FAILURE;
    }
    if (sscanf(riga, "%d %c", &posto, &extra) != 1) {
        fprintf(stderr, "Errore: formato del posto non valido.\n");
        return EXIT_FAILURE;
    }
    if (posto < 1 || posto > 15) {
        fprintf(stderr, "Errore: il posto deve essere compreso tra 1 e 15.\n");
        return EXIT_FAILURE;
    }

    fprintf(stdout, "Prenotazione confermata: fila %d, posto %d\n", fila, posto);
    if (fila <= 5) {
        fprintf(stdout, "Settore: Platea anteriore\n");
    } else if (fila <= 12) {
        fprintf(stdout, "Settore: Platea centrale\n");
    } else {
        fprintf(stdout, "Settore: Platea posteriore\n");
    }
    if (posto == 1 || posto == 15) {
        fprintf(stdout, "Posizione: Corridoio\n");
    } else {
        fprintf(stdout, "Posizione: Interno\n");
    }
    return EXIT_SUCCESS;
}

#include <stdio.h>
#include <stdlib.h>

int main(void) {
    int c1 = getchar();
    int c2 = getchar();
    int c3 = getchar();
    int c4 = getchar();
    int c5 = getchar();

    if (c1 == EOF || c2 == EOF || c3 == EOF || c4 == EOF) {
        fprintf(stderr, "Errore: codice incompleto (fine dell'input).\n");
        return EXIT_FAILURE;
    }
    if (c5 != '\n' && c5 != EOF) {
        fprintf(stderr, "Errore: il codice deve avere esattamente 4 caratteri.\n");
        return EXIT_FAILURE;
    }
    if ((c1 != 'A' && c1 != 'B' && c1 != 'C') ||
        c2 < '0' || c2 > '9' || c3 < '0' || c3 > '9' || c4 < '0' || c4 > '9') {
        fprintf(stderr, "Errore: formato codice non valido.\n");
        return EXIT_FAILURE;
    }

    int d1 = c2 - '0';
    int d2 = c3 - '0';
    int d3 = c4 - '0';
    int numero = d1 * 100 + d2 * 10 + d3;
    int somma_cifre = d1 + d2 + d3;
    int controllo = somma_cifre % 10;

    printf("Codice verificato: ");
    putchar(c1);
    putchar('-');
    putchar(c2);
    putchar(c3);
    putchar(c4);
    putchar('-');
    putchar('0' + controllo);
    putchar('\n');

    switch (c1) {
        case 'A':
            printf("Settore: Archivio\n");
            break;
        case 'B':
            printf("Settore: Biblioteca\n");
            break;
        default:
            printf("Settore: Centro calcolo\n");
            break;
    }
    printf("Numero: %d\n", numero);
    printf("Somma cifre: %d\n", somma_cifre);
    return EXIT_SUCCESS;
}
